import{_ as a,o as t,c as s,a3 as e}from"./chunks/framework.DdpBa4_E.js";const _="/ReadBooks/assets/image-023.Box4JUri.jpg",o="/ReadBooks/assets/image-031.B2RtHmrW.jpg",i="/ReadBooks/assets/image-080.DM_WozDw.jpg",r="/ReadBooks/assets/image-040.BFKvGU0Z.jpg",k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/46-年入400万日元是女性脱离“下流”的必需条件.md","filePath":"books/xialiu-shehui/46-年入400万日元是女性脱离“下流”的必需条件.md","lastUpdated":1794732511000}'),l={name:"books/xialiu-shehui/46-年入400万日元是女性脱离“下流”的必需条件.md"};function d(n,p,u,c,m,g){return t(),s("div",null,[...p[0]||(p[0]=[e('<h2 id="年入400万日元是女性脱离-下流-的必需条件" tabindex="-1">年入400万日元是女性脱离“下流”的必需条件 <a class="header-anchor" href="#年入400万日元是女性脱离-下流-的必需条件" aria-label="Permalink to &quot;年入400万日元是女性脱离“下流”的必需条件&quot;">​</a></h2><p>然而并非说不结婚的女性其阶层意识就一定低下，未婚且独身一人生活的女性，在28岁之后阶层意识呈“下流”的人数反而有所减少（见图4-5）。</p><p><img src="'+_+'" alt="" loading="lazy"></p><p>图4-5　未婚独身一人生活的女性中“下流”阶层意识的各年龄段人数比例资料出处：Culture Studies研究所、读卖广告社共同实施的“第一次女性阶层化调查”</p><p>独身一人生活的女性，其收入自然较高。据说年收入超过400万日元，无论男性女性都会倾向于独身生活（参见宫本美智子著《后青年期与亲子战略》）。</p><p>事实上，根据“第一次女性阶层化调查”的数据，在23—27岁、年收入超过400万日元的女性中，有60%以上的女性过着独自一人的未婚生活（见表4-13）。此外，同一调查还显示：个人的年收入低于400万日元的女性中，有50%的人其阶层意识为“下流”，而年收入在400万—799万日元的女性中，这一比例则减少至27.3%（见表4-14）。可见，年收入400万日元是脱离下流阶层意识的最低底线。</p><p>表4-13　不同收入层次女性的婚姻状况及家庭形态（23—27岁）</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、读卖广告社共同实施的“第一次女性阶层化调查”</p><p>表4-14　不同收入层次女性的阶层意识（18—37岁）</p><p><img src="'+i+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、读卖广告社共同实施的“第一次女性阶层化调查”</p><p>按照这一推论来分析，随着年龄增大，独身生活的女性其下流阶层意识比例有所减少与其说是因为未婚而引致的阶层意识低下的作用，不如说是由于收入增多而产生的阶层意识提升所起的作用更大。当然，随着年龄不断增大，未婚女性已经渐渐适应了这种独身生活，并且从中体验到一种轻松、随意的生活乐趣也是原因之一。</p><p>故此，“啃老族”女性随着年龄增大其阶层意识呈现“下流化”的最大理由，前述的假设3似乎最具说服力。概括起来说，就是年龄在不断增大而收入却仍旧低于400万日元的话，就可能对其阶层意识的低下产生显著的影响。</p><p>事实上，23岁以上、年收入超过400万日元的女性中，阶层意识为“上流”的人数众多，并且越是年龄大，其比例也越是增多（见图4-6）。可见只要拥有超过400万日元的年收入，即使是年逾30岁仍旧未婚的女性，照样能够生活得很幸福。</p><p><img src="'+r+'" alt="" loading="lazy"></p><p>图4-6　年收入400万以上的女性中“上流”阶层意识的各年龄段人数比例资料出处：Culture Studies研究所、读卖广告社共同实施的“第一次女性阶层化调查”</p><p>花边外谈1：永恒的门当户对婚嫁观念</p><p>《朝日周刊》自1979年以来便开始刊出一组长篇连载，题目叫：“郎‘财’女貌”（最初题为“夸一夸我家的新媳妇”），讲述具有一定经济和社会地位的父亲，其子大都顺利地进入大企业工作，然后迎娶一位聪慧、性格开朗、品位高雅的女性为妻的千年不变的门当户对婚嫁故事。</p><p>由于近年来年轻人中盛行晚婚，因此要想发掘到一组合适的采访对象就成了一桩颇不容易的事情（或许是因为这个原因，采访对象中父亲是原日本银行干部的例子特别多）。尽管如此，这个旨在宣扬门当户对才是人间婚姻幸福的长篇连载居然持续了这么长久，可见过去20多年间日本社会阶层固定化的情况相当严重。假如觉得《朝日周刊》的连载与自己的生活相距太大，因而引不起兴趣的话，也可以去看一下《朝日演艺》一类杂志中的文章，这些文章选取的角度不同，但宗旨却是相同的。那里刊登的故事多为父亲是“下只角”的手工匠人、儿子是经营情人旅馆的、儿媳曾经是从事色情服务的小姐，或者父亲是卡车司机、儿子是脱衣舞俱乐部的老板、儿媳原来是一名飞车党成员之类，由于门当户对，居然也能读出一幅幅幸福家庭的画面。</p><p>请看《朝日周刊》最近几期刊出的门当户对的几组例子：</p><p>父亲——原日本银行干部</p><p>儿子——三菱商事职员</p><p>儿媳——与儿子同在一家公司，擅长烹饪，爱好园艺，家中庭院里四季各种花草不绝父亲——高级餐馆的老板兼主厨儿子——日本旅行社职员儿媳——爱好运动、性格爽朗父亲——电通广告公司董事儿子——东京广播公司（TBS）职员儿媳——女性杂志专栏作家，品位卓尔不群，头脑敏锐，待人热心诚恳父亲——原日本银行干部儿子——三菱信托银行职员儿媳——与儿子同年进入同一银行，做事精干、能力出众父亲——酿酒公司社长儿子——麒麟啤酒公司职员儿媳——性格开朗、魅力十足父亲——原警视总监儿子——瑞穗银行职员儿媳——原商社职员，日语讲师</p>',24)])])}const B=a(l,[["render",d]]);export{k as __pageData,B as default};
